  if(t.pattern==='spots'&&(B.id==='forest'||B.id==='grassland'||B.id==='freshwater'))camo=Math.min(1,camo+.1);
  if(t.pattern==='stripes'&&t.social==='herd'&&B.id==='grassland')camo=Math.min(1,camo+.35);
